mapper.select:
SELECT tenant_id, api_id, api_code, api_name, req_json FROM bt_skill_plugin a WHERE a.status_cd = '00A'
AND (a.api_code LIKE
#{query.searchContent}
OR a.api_name LIKE
#{query.searchContent}
)
AND a.catalog_item_id IN (#{catalogItemId})
AND a.tenant_id = -1
AND a.tenant_id = #{query.tenantId}
AND a.tenant_id IN (#{query.tenantId}, -1)
ORDER BY a.updated_time DESC
